import type { RuleId } from "./rules/ids.ts";

// What to do, for every rule (spec section 6, "What to do"): every alert carries one. Values come from
// the finding's facts where a line needs them (a deadline, an address, a link). Actions are always done
// from the owner's own tools, never from a link in an email.

type Facts = Record<string, string>;
const or = (v: string | undefined, fallback: string) => (v && v.length ? v : fallback);

const standby = (f: Facts) => f.validator?.startsWith("standby") === true;
/** The standby's way back (Task 68 listed it with addHotkey and moved about 10% of the stake onto it): its stake moves
 * onto the stake hotkey with moveStake (scheduled, 48 hours), then the empty hotkey is removed. */
const STANDBY_BACK =
  "Move its stake back to the primary: owner, schedule moveStake(<the standby>, <its stake in rao>) (pnpm ops schedule, 48 hours; it moves onto the stake hotkey), claim the standby's rewards (pnpm ops claim), then removeHotkey(<the standby>, false) once it is empty. Then choose another standby, or none, and set STANDBY_HOTKEY to match.";

/** ForeverMoney's rail in doubt on v3.2 (rail.pool, fmtao.unbacked, fmtao.backing_true's alpha side,
 * fmtao.role_change_critical, fmtao.rebalancer_set): a paused front door stops only deposit, depositFor and deliver,
 * never a close (I-20; closeBatch is anyone's). The real options: the vault's pause (no payout is sent), the guardian's
 * disableBridge of the front door's primary (no batch closes, and no redeem leaves Base: the founder's call), and the
 * owner's cancelPayoutBatch of a batch not yet sent (its unsent redeems get their shares back; CascadeVault.sol). */
const DOOR_PAUSE_V32 = "On v3.2 a paused front door never stops a close (anyone can close a due batch): it stops only deposit, depositFor and deliver.";
const GUARDIAN_V32 = (then: string) =>
  `Guardian: pause() the vault (no payout is sent into the rail) and the front door (no new stake or delivery), and ${then}. To keep the open batch from crossing too, the guardian can disableBridge(<the primary bridge>) on the front door: closes then revert (PrimaryBridgeDisabled), and no redeem leaves Base until the owner reopens it (a scheduled activateBridge, or setPrimaryBridge to another enabled bridge). That trade-off is your call.`;
const CANCEL_V32 =
  "If it lasts, owner: cancelPayoutBatch(key, payouts) on each payout batch not yet sent (the list rebuilt from the vault's events for its key): its unsent redeems get their shares back instead of TAO sent into the rail (bounced deposits stay queued: they are owed TAO). A cancel is an owner action: it stamps the owner's clock, which kills every owner item scheduled until then, so schedule again any you still want.";
const RAIL_V32 = (then: string) => `${DOOR_PAUSE_V32} ${GUARDIAN_V32(then)} ${CANCEL_V32}`;
const RAIL_POOL_V32 = RAIL_V32("ask ForeverMoney what changed");
/** rail.payouts_closed: what becomes of the open batch's redeem requests while the vault's primary can't send payouts,
 * and the close (runbook 7.7: closes need no stopping, since the vault defers door redeems rather than burns them). */
const OPEN_BATCH_CLOSED = (when: string, again: string) =>
  `The open batch's redeem requests are deferred ${when}: the requesters keep their shares and their request fees are spent; tell them to ask again ${again}, or to leave directly on Bittensor with a regular wallet (/unstake/bittensor/). There is no need to hold the close: the vault takes nothing from them, and holding it would hold the batch's deposits too (runbook 7.7).`;

/** guardian.low_eth and guardian.low_tao: the offline pause needs the same gas, and a balance that fell with nothing
 * signed is a sweeper's (a copied seed drains the owner's and the guardian's accounts and front-runs every refill:
 * runbook 7.2, "never refill a swept account"). */
const GUARDIAN_GAS =
  "The offline pause kept ready (runbook 3.6: pnpm ops pause both --for-wallet --offline) fixes no gas or fee, so it needs this balance too. First make sure you spent it yourself (a pause, a drill): the guardian pays gas only for what you sign with it. If its balance fell and you signed nothing, someone else has its key. Never refill a swept account: follow runbook 7.2 (a copied seed) or 7.3 (a stolen guardian).";

export const RUNBOOK: Record<RuleId, (f: Facts) => string> = {
  "price.drop": () =>
    "Find the cause before anything else moves (the stake hotkey and the vault's stake on taostats). If stake left the hotkey set or the drop is unexplained, guardian: pause() the vault so no batch is priced low; re-add a swapped hotkey with addHotkey.",
  "stake.unexplained_drop": (f) =>
    `Stake left the vault without a vault action: look up the hotkey ${or(f.hotkey, "")} on taostats (swap, slash, chain change). Guardian: pause the vault until it is explained.`,
  "stake.hotkey_changed": () =>
    "A hotkey change the owner didn't make means a validator-side swap: re-add the new hotkey with addHotkey (owner, guardian or keeper) and check the price.",
  "stake.divergence": (f) =>
    `The vault's counted stake fell by what now sits on hotkey ${or(f.hotkey, "(see the facts)")} (${or(f.stake, "see the facts")}), which the vault doesn't list, so rootStakeRao() and the share price don't count it: a validator's hotkey swap (the stake moved to its new hotkey), or stake moved off a listed hotkey. Until it is listed again, shares mint cheaply at the depressed price (a batch delivery, depositDirect). Guardian: pause() the vault now (deliveries, direct deposits and payouts stop). Then owner, guardian or keeper: addHotkey(${or(f.hotkey, "<the hotkey>")}) to bring the stake back into the price (the set holds at most 4: owner removeHotkey an empty one first if it is full). Check on taostats${f.taostats ? ` (${f.taostats})` : ""} that the stake is there and who owns the hotkey now, check the price recovered, then clear the hold${f["the hold"]?.startsWith("on, from") ? ` (${f["the hold"].slice(9)}'s: this alert raised none of its own)` : ""} and unpause.`,
  "stake.unlisted": (f) =>
    f.contracts === "v3.2"
      ? `${or(f.stake, "Stake")} sits on ${f.hotkey?.startsWith("0x") ? `hotkey ${f.hotkey}` : "a hotkey"} under the vault's coldkey that the vault doesn't list, and nothing is missing: a stranger's transfer_stake gift, or the vault's own stake back after a write-off. It isn't in the share price. Since nothing is missing, no stranger can list it and the last of the 4 slots stays shut: only the owner, guardian or keeper can. To bring it in: addHotkey(${f.hotkey?.startsWith("0x") ? f.hotkey : "<the hotkey>"}), then the keeper's adoptStake books it into the price (at most once a day; vault.stake_adopted says when). Not worth a transaction for dust: acknowledge it.`
      : `${or(f.stake, "Stake")} sits on hotkey ${or(f.hotkey, "(see the facts)")} under the vault's coldkey, which the vault doesn't list, and the vault's counted stake didn't fall by it: a stranger's transfer_stake (anyone can push stake onto any coldkey; the minimum is about 0.0005 TAO), not a swap, so nothing is held. Its depositors get it through their shares once it is counted: owner, guardian or keeper addHotkey(${or(f.hotkey, "<the hotkey>")}) (the set holds at most 4), then owner removeHotkey(${or(f.hotkey, "<the hotkey>")}, true), which moves the stake onto the stake hotkey (or unstakes dust below the chain's minimum). Not worth a transaction for dust; acknowledge it then. If the counted stake does fall later, stake.divergence takes over with a hold.`,
  "admin.event": (f) =>
    `An admin action on a Cascade contract${f.sender ? `, sent by ${f.sender}` : ""}. If it was a planned change, acknowledge it. If not: guardian pause() both contracts now, then rotate keys.`,
  "admin.scheduled": (f) =>
    `An owner change was scheduled on the ${or(f.contract, "contract")}. If you scheduled it, check the change and its arguments above are what you meant, then acknowledge. If you didn't, someone has the owner key: before ${or(f["ready at"], "it is ready")}, sign an owner stamp (pnpm ops stamp) and have any funded account relay it; that kills every item scheduled until then. ${f.kind?.startsWith("Ordinary") ? "The guardian can also cancel this one (cancel(id)). " : ""}Then move the owner to a new key.`,
  "admin.executed": (f) =>
    `A scheduled owner change took effect on the ${or(f.contract, "contract")}. If it is yours, acknowledge. If you didn't schedule it, someone has the owner key and the change is live: guardian pause() the vault (on Base, disableBridge of the primary bridge), then undo the change and move the owner to a new key.`,
  "admin.cancelled": (f) =>
    `A scheduled owner change was cancelled${f["cancelled by"] ? ` by ${f["cancelled by"]}` : ""}. If you or your guardian did it, acknowledge. If neither of you did, that key is in someone else's hands: rotate it.`,
  "admin.lapsed": () =>
    "A scheduled owner change can no longer run (why is above). If you still want it, schedule it again: a new delay starts. Schedule after any closure or stamp you plan, so they don't kill it.",
  "admin.item_loosens": (f) =>
    `A pending owner change would now loosen a limit when it runs: a direct change since it was scheduled moved the current value past it. If you still want it, acknowledge. If not, cancel(id) it before ${or(f["ready at"], "it is ready")} (the owner, or the guardian for an Ordinary item).`,
  "admin.hotkey_switched": (f) =>
    `The owner switched the vault's stake hotkey at once${f.hotkey ? ` to ${f.hotkey}` : ""}. It can only do that when the new hotkey already holds more stake than the old one and at least half the booked stake, and gifts count. If it was you, following a validator's hotkey swap, acknowledge. If not, someone has the owner key and the vault's rewards now go through that validator: guardian pause() the vault, move the owner to a new key, then switch back with a scheduled setStakeHotkey.`,
  "admin.exits_state": (f) =>
    f["active doors on Base"] !== undefined
      ? "The vault has no active front door on Base: Base users can't leave through the door, only by a direct exit on Bittensor. Schedule the door's activateFrontDoor (7 days), or its Reopen if the owner removed it."
      : `Exits are closed on the ${or(f.contract, "contract")} (${or(f.holds, "see the holds above")}). If you closed them on purpose, finish and reopen. If not, find out who did: an owner hold only the owner can lift (unpause, or the Reopen of the bridge or the door); a guardian hold ends with the guardian (owner: schedule setGuardian, 8 days). While closed, no Ordinary item can be scheduled or run, and the ones pending when it closed can never run.`,
  "rails.incoherent": (f) => {
    // R6 (claim D): the batches are taken, but the vault's own primary is disabled (src/rules/rails.ts)
    const noRail = /no payout rail/.test(f.parked ?? "");
    const effect =
      f.direction === "payouts"
        ? "payouts to Base are refused"
        : noRail
          ? "unstakes from Base are deferred"
          : f.parked?.startsWith("no")
            ? "deposits from Base are refused"
            : "deposits from Base are refused and parked (refunded to Base after 14 days)";
    // a primary disabled on its own side (src/rules/rails.ts): its Reopen fixes it, or a switch of both sides
    const own = f["disabled primary"];
    const lead = own ? `The ${own.includes(" on the vault ") ? "vault" : "front door"}'s primary bridge is disabled` : "The two chains disagree on the bridge";
    // halves that don't name each other, or a wrong chain: the adapters' immutables
    const fixed = /takes messages only from|sends to chain/.test(f.why ?? "");
    const fix = fixed
      ? "The adapters' peers are fixed at deploy, so the only fix is to move both sides to a correct pair."
      : noRail
        ? "Switch the vault's primary first (runbook section 8): its setPrimaryBridge to the bridge the front door's batches reach, which takes effect at once."
        : own
        ? "Reopen it, or switch both sides to another pair."
        : "Finish the two-sided switch, or switch the other side back.";
    return `${lead}, so ${effect}${f.why ? `: ${f.why}` : ""}. ${fix} Both sides must end on the same pair of bridges, and a bridge must be enabled on its own chain before it can be the primary (owner: activateBridge, 7 days). A guardian can't fix it alone: only the owner can enable a bridge or switch the primary. This alert holds the keeper: clear the hold once it clears.`;
  },
  "admin.owner_pending": (f) =>
    `An ownership transfer has run, and ${or(f["pending owner"], "the new owner")} can accept${f["it can accept until"] ? ` until ${f["it can accept until"]}` : ""}. If it is your own move (to a Safe), accept from the new owner and acknowledge. If not, someone has the owner key: refuse the acceptance now with any closure (guardian pause() the vault; on Base, disableBridge of the primary bridge) or a relayed owner stamp.`,
  "admin.owner_kind": () =>
    "The owner is one key, not a Safe needing 2 of 3 signers, while Cascade is past the founder level. A stolen or copied key could then make changes after only their delay. Move the owner to a 2-of-3 Safe on both chains: schedule transferOwnership to it (8 days), then accept from the Safe.",
  "admin.record_full": (f) =>
    `More owner changes are scheduled than the monitor tracks (${or(f.tracked, "256")} tracked, ${or(f["not tracked"], "more")} beside them). Each one was still emailed, but those not tracked aren't judged or shown on the security page until there is room for them. That many is almost certainly someone with the owner key: relay an owner stamp now (pnpm ops stamp), which kills every item scheduled until then, and move the owner to a new key. This clears once each one not tracked is tracked, has run or been cancelled, or is past its window.`,
  "vault.stake_adopted": () =>
    "The vault booked stake it held beyond its books (a gift onto its hotkeys, or stake back after a write-off) into the share price. It is added gradually on its own drip, over the reward vesting period (rewardVesting), and never restarts the claimed rewards' schedule. The keeper does this at most once a day. Nothing to do unless the amount surprises you: then check the vault's stake on taostats.",
  "stake.set_full": () =>
    "Stake is missing (most likely a validator's hotkey swap), and the vault's hotkey set is full: the swap's new hotkey can't be listed until a slot is free, and only the owner can free one, since every other hotkey holds stake or unclaimed rewards. Until then the vault refuses deposits and withdrawals. Owner: claim the rewards of a hotkey that isn't the stake hotkey (pnpm ops claim), removeHotkey(<that hotkey>, false) (at once; its stake moves onto the stake hotkey), then addHotkey(<the swap's new hotkey>).",
  "stake.writeoff_read_gas": (f) =>
    `The vault's write-off checks the unlisted stake with one read whose gas grows with every position on the vault's coldkey, on any subnet, and anyone can add a position under a hotkey the vault ever listed; none can be removed. It costs ${or(f["the read's gas now"], "more than the warning's threshold")} gas now, of the vault's 45,000,000 cap. Past the cap the vault's own check fails open: a write-off then rests on pnpm ops execute's check and the guardian's veto alone. Nothing to do now: if it keeps rising, plan the next vault before other people's money.`,
  "stake.writeoff_bound_off": (f) =>
    f["the lens read"]?.startsWith("unlistedStakeRao() answers")
      ? `The vault's write-off bound reads the unlisted stake with the staking precompile's getTotalColdkeyStakeOnSubnet, and that read now costs more gas than the ${or(f["the vault's cap (WRITE_OFF_READ_GAS)"], "45,000,000")} the vault gives it (${or(f["the read's gas estimate"], "over the cap")}): the lens's own read still answers, but the vault's capped one fails and the vault takes a failure as 0, so while this lasts a write-off would run with no bound, writing off stake the holders still own. Its cost grows with every position on the vault's coldkey, on any subnet (stake.writeoff_read_gas warned of the climb), and none can be removed. Check pnpm ops pending --live for a scheduled writeOffMissingStake; if there is one you didn't schedule, guardian: cancel it (pnpm ops cancel <id> --as guardian --for-wallet --live, then pnpm ops sign <file>). pnpm ops execute's own read is uncapped, so it still sizes a write-off by the unlisted stake, but nothing on chain bounds what the owner's key sends. Schedule no write-off while this lasts, and plan the next vault (a fresh coldkey) before other people's money.`
      : `The vault lens's unlistedStakeRao() reverts: it totals the vault's coldkey with the staking precompile's getTotalColdkeyStakeOnSubnet, the same read the vault's write-off bound makes. The vault gives that read ${or(f["the vault's cap (WRITE_OFF_READ_GAS)"], "45,000,000")} gas and takes a failure as 0, so while this lasts a write-off would run with no bound, writing off stake the holders still own. Nothing anyone can do on chain causes it today, so most likely a runtime upgrade removed that function or changed what it answers or costs. Check pnpm ops pending --live for a scheduled writeOffMissingStake; if there is one, guardian: cancel it (pnpm ops cancel <id> --as guardian --for-wallet --live, then pnpm ops sign <file>). pnpm ops execute refuses a write-off while this read fails, but nothing on chain stops the owner's key sending one. Schedule no write-off until the read answers again (the runbook's capped read before a write-off, section 7.5), and find what changed in the runtime (its specVersion, Bittensor's release notes).`,
  "stake.missing_small": () =>
    "A little of the vault's booked stake isn't on its hotkeys (most likely a validator moved a small position), too little for the vault to stop deposits. List the hotkey it moved to now (addHotkey, as the owner, guardian or keeper: a stranger can't while nothing reads missing): listing it closes the gap, since the stake there is the booked stake, seen again; every deposit until then mints at a price that leaves the gap out, and gains from the holders once the stake is listed. adoptStake has no part in it: it books only stake above the booked (a surplus). If it is on no hotkey of the vault's coldkey, it is gone: acknowledge it.",
  "stake.missing": (f) =>
    `The vault's booked stake isn't on the hotkeys it lists${f["the hotkey whose stake fell"]?.startsWith("0x") ? ` (it left ${f["the hotkey whose stake fell"].slice(0, 66)})` : ""}: most likely a validator's hotkey swap moved it to a new hotkey. Nothing is lost, and the vault guards itself: it mints nothing while this lasts, so a batch delivery parks in the Bittensor adapter (bridge.parked), a direct deposit reverts, and a direct redeem needs acceptMissing. Find where the stake went on taostats${f.taostats ? ` (${f.taostats})` : ""}, then list that hotkey: addHotkey(<the new hotkey>). Anyone may while stake is missing, if the vault never listed it and it holds at least the chain's minimum; otherwise the owner, guardian or keeper. If the set is full, see stake.set_full. Once it clears, the keeper delivers the parks (deliverParked). The swap's own fall raises no stake.unexplained_drop and holds nothing; one raised beside this is a fall the swap doesn't explain (most likely stake that left the vault's coldkey), and its hold stops the keeper until you find the cause and clear it. Only if the stake is really gone: the owner schedules writeOffMissingStake (7 days; the guardian can veto it).`,
  "stake.surplus_unadopted": () =>
    "The vault holds stake beyond its books (a gift onto its hotkeys, or stake back after a write-off) that isn't in the share price yet, and it has waited more than a day though adoption is allowed (time the vault is paused isn't counted: adoptStake waits for the unpause). The keeper adopts it (adoptStake) at most once a day: check the keeper runs and has TAO. Anyone can call adoptStake after the keeper's fallback (7 days). Nothing is at risk meanwhile.",
  "stake.unstake_skipped": (f) =>
    `The vault's unstake walk tried this hotkey ${or(f.skips, "several times")} and the chain refused each removal, or it ran out of the gas it was given${f["the chain's root stake hold"] && !f["the chain's root stake hold"].startsWith("none") ? ` (the chain's root stake hold is set: ${f["the chain's root stake hold"]}; see root.hold_interval)` : " (see root.hold_interval: a hold on the pair is the usual cause)"}. Each exit took its TAO from the other hotkeys, or reverted and waits. Nothing is lost. Check the hotkey on taostats${f.taostats ? ` (${f.taostats})` : ""}. If it is gas, the owner can raise the vault's unstakeGas; if it lasts and exits stall, see payout.overdue.`,
  "stake.min_raised": (f) =>
    `Bittensor's minimum stake rose${f.after ? ` to ${f.after}` : ""}. The vault's unstake walk skips a position below it, and after a swap a stranger can list the new hotkey only if it holds at least the minimum: a smaller swapped position is then cleared only by the owner or a gift. ${f["listed positions below it"] && f["listed positions below it"] !== "none" ? `Below it now: ${f["listed positions below it"]}. Owner: claim its rewards (pnpm ops claim), then removeHotkey(<it>, false), which moves its stake onto the stake hotkey.` : "No listed position is below it: acknowledge."}`,
  "keys.unexplained_tx": (f) =>
    `A transaction left a Cascade admin key that didn't touch Cascade (or reverted). Open the address on the explorer${f.explorer ? ` (${f.explorer})` : ""}. If it isn't yours, treat the key as compromised: guardian pause, rotate. The rule is quiet only while these keys are used for Cascade alone; acknowledge your own other transactions. On v3-test owner, guardian and keeper are one address, so a reverted keeper call pages here: expect that noise there.`,
  "keys.delegated": (f) =>
    `A role wallet was delegated or its code changed.${f.address ? ` The wallet: ${f.address} (${or(f.roles, "a role")}), ${or(f.before, "before unknown")} then ${or(f.now, "now unknown")}${f.explorer ? `; ${f.explorer}` : ""}.` : ""} First check whether it was your own wallet's smart-account upgrade (then acknowledge, and clear the hold). If not, assume its key is compromised: Guardian pauses; rotate the role. If the guardian itself is the wallet, pause from the owner, and the other way round. Clear the hold only once the role is rotated.`,
  "keys.safe_unread": (f) =>
    `A watched Safe's nonce()${f.address ? ` (${f.address}, ${or(f.roles, "a role")})` : ""} hasn't answered for ${or(f.ticks, "many")} ticks, so it isn't being judged: the transactions it executes are still counted, but keys.unexplained_tx can only judge them, late, once nonce() answers again. Check the Bittensor or Base RPC, and the address's code on the explorer${f.explorer ? ` (${f.explorer})` : ""}: a node misreading it, or the address no longer a Safe (then keys.delegated or keys.code_changed says so).`,
  "keys.count_unread": (f) =>
    `The transaction counts of the watched keys on ${or(f.chain, "a chain")}${f.addresses ? ` (${f.addresses})` : ""} haven't been read for ${or(f.ticks, "many")} ticks in a row: their batch keeps failing (usually the RPC rate-limiting it, HTTP 429), so keys.unexplained_tx and keys.keeper_unexplained_tx judge nothing meanwhile, and keys.delegated, whose code reads ride in the same batch, is blind. Transactions that settle meanwhile are still counted, and a key's count is judged again as soon as one is read, so nothing is lost, only late. Check ${f.chain === "bittensor" ? "BITTENSOR_RPC_URL" : f.chain === "base" ? "BASE_RPC_URL" : "the chain's RPC URL"} (or its _SECRET) and the Worker's log ("transaction counts failed"); if it stays down, switch to another provider and redeploy. Until then, check the watched keys on the explorer yourself. It resolves on the next tick that reads the counts.`,
  "keys.code_changed": (f) =>
    `A role wallet's code changed in a way a stolen key alone can't cause${f.address ? ` (${f.address}, ${or(f.roles, "a role")}: ${or(f.before, "before unknown")} then ${or(f.now, "now unknown")})` : ""}: a contract deployed at an address that had none (a counterfactual Safe), or a 7702 delegation removed. First check whether it was your own wallet's smart-account change, and acknowledge it. If you didn't deploy it, treat it as critical: someone else can deploy a contract at a role address that wasn't deployed yet, as happened to Wintermute's Safe address on Optimism in 2022, and then controls it (guardian pauses; rotate the role). The new code is the baseline now: a later change of it is critical.`,
  "frontdoor.solvency": () =>
    "The front door holds less than it owes. Guardian: pause() the front door (claims and cancels still work); find the transfer that broke the identity.",
  "vault.solvency": () => "The vault can't cover its queued payouts. Guardian: pause the vault; do not process payouts.",
  "ccip.failure": (f) =>
    `The message and its tokens wait in CCIP. Open it on ccip.chain.link${f.ccip ? ` (${f.ccip})` : ""} and note the reason; it can be executed again by hand once the cause is fixed. Two causes need no fix of ours: a stranger can move an untouched message to FAILURE (re-execute it at once; no committee results are needed), and the inbound rate limit can fail a delivery before ccipReceive (wait for it to refill, see ccip.rate_limited, then re-execute). Don't pause anything else for this alone, except: if an honest batch failed with DuplicateBatch, a byte-identical copy was delivered first, and this alert may be the only sign of it. Then treat it as bridge.batch_mismatch (guardian pause the vault, check the batch's deliveries).`,
  "ccip.unexpected_source": (f) =>
    `A Cascade contract accepted a message from an unexpected sender. Treat it as a forgery: follow the steps for ${f.side === "base" ? "bridge.payout_mismatch (guardian pause the front door; tell ForeverMoney and Chainlink)" : "bridge.batch_mismatch (guardian pause the vault; owner cancelPayoutBatch before the deadline)"}.`,
  "deposits.bounced": (f) =>
    f.reason?.startsWith("ForeignOrigin")
      ? "The vault returned a deposit: its address redeems through another chain's front doors (its redeem origin), so this door can't credit it. Nothing is lost: it goes back to Base with the batch's payouts; process the bounced payout, never cancel it. The holder can change its origin on Bittensor (setRedeemOrigin) before depositing here again."
      : "The vault read itself as insolvent and returned the deposits. Find out why (price, stake) before the next batch; process the bounced payout, never cancel it.",
  "vault.deposits_refused": (f) =>
    `The vault's share price (${or(f["share price"], "see the facts")}) is below half the launch price: assets were lost, so it refuses every new deposit, which would buy shares too cheaply. A batch's deposits bounce back to Base (deposits.bounced) and a direct deposit reverts; exits still work. Find the loss first: stake.missing, stake.unexplained_drop, vault.solvency, price.drop. Guardian: pause() the front door so no one stakes into a batch that will bounce. It clears only when the assets come back (a swapped hotkey listed again).`,
  "stake.removal_fee": (f) =>
    `Bittensor kept part of a root unstake (${or(f["the chain kept"], "see the facts")}): it may now charge a removal fee. Nothing is lost by the holders: the exit that unstaked pays it (the leaver pays). Check the transaction's receipts on the explorer. If it is a real fee, the site's exit quote must show it (its "unstake fee" line, from the fee per removal seen here), and the last batch of an emptying vault may need a small stake gift to cover it. Raise it with the Bittensor team.`,
  "swap.below_oracle": (f) =>
    `${f.trade === "a stake" ? "A stake" : "A USDC delivery"} Cascade settled for a user landed ${or(f["below the oracle"] !== "none" ? f["below the oracle"] : f["below it"], "more than 1%")} below a fair price: the user got less than they should. The floors on chain allow up to 5% for a stake and 1.5% for a delivery, so this isn't a revert. Look at the transaction on Basescan for a swap just before it in the same block (a sandwich), or a thin pool. A large trade moves the price by itself: the site warns above 1% of price impact. If you see a pattern, guardian: pause() the front door (stops new stakes and deliveries) while you look.`,
  "fmtao.unbacked": (f) =>
    `TAO on Base isn't fully backed. ${f.contracts === "v3.2" ? RAIL_V32("tell ForeverMoney and Chainlink") : "Guardian: pause the front door (stops new batches and deliveries); tell ForeverMoney and Chainlink; hold payouts until it is explained."} Its blind spot: the lock pool also backs FM-TAO on Robinhood (and any other lane it serves), which this check can't read, so Base's supply can stay under the whole lock while the lock no longer covers every lane; fmtao.backing_true watches the lock against wTAO's supply instead.`,
  "fmtao.depeg": () => "TAO on Base trades away from TAO. Guardian: pause the front door if it persists; deliveries' floors stop sales into a crashed pool.",
  "bridge.batch_mismatch": (f) =>
    `Possible forged batch. Guardian: pause() the vault now. Owner: cancelPayoutBatch(key, payouts) before ${or(f.deadline, "the payout delay ends (queued time + payoutDelay)")}, with the list rebuilt from the vault's events for this key. Keep the hold until the cancel lands.${f.contracts === "v3.2" ? " On v3.2 a cancel re-mints at the lower of the booked and visible stake, so while stake is missing (stake.missing) it returns fewer shares: if the cancel can wait for the deadline, restore the stake first." : ""}`,
  "bridge.payout_mismatch": () =>
    "Possible forged payout: TAO was minted on Base for it. Guardian: pause() the front door (deliveries stop; claims can't be stopped); tell ForeverMoney and Chainlink; keep the hold.",
  "bridge.duplicate": (f) =>
    `One message delivered twice under different content. As ${f.side === "base" ? "bridge.payout_mismatch (guardian pause the front door; keep the hold)" : `bridge.batch_mismatch (guardian pause the vault; owner cancelPayoutBatch before ${or(f.deadline, "the payout delay ends")})`}.`,
  "site.integrity": () =>
    "The site may be tampered with. Take it down (the cascade-site Worker: roll back its deployment, or remove its route), then check DNS, the build and the Worker. A page whose Content-Security-Policy differs in more than the inline scripts' hashes (those alone are site.stale_lists): compare its header (curl -sI the page) with that page's rules in web/out/_headers of the build deployed; a new host, 'unsafe-inline' or 'unsafe-eval', or a directive or policy gone is tampering until shown otherwise. If a file was over the byte cap and is a legitimate large chunk, raise SITE_MAX_BYTES; if a file stopped a run, that is the CPU limit (Workers Paid, or SITE_FILES_PER_RUN=1), not the byte cap. What Cloudflare itself injects must be approved too, once checked to be Cloudflare's: a script loaded from its host (the Web Analytics beacon) with pnpm site:approved ../web/out --extra-script-hosts <host>, a host one of its /cdn-cgi/ scripts names with --extra-hosts <host>, then redeploy. A script host the bundle merely names (a gateway such as arweave.net or ipfs.io in a dependency) is never approved as a script source by that. The limits of this check: it reads the scripts' text, so an address or host built at run time (by string concatenation, or fetched from elsewhere) isn't seen, and a site that serves the monitor a clean copy and users a tampered one can't be caught from outside.",
  "site.stale_lists": () =>
    "The site was deployed but the monitor's approved lists weren't regenerated (every build changes its inline scripts' hashes). Run pnpm --dir indexer site:approved ../web/out on the exact out/ that was deployed (a rebuild changes every hash), commit, and redeploy the monitor. If nobody deployed the site, treat it as site.integrity: a page now allows an inline script the approved build didn't have.",
  "site.redeploy_race": () =>
    "In each of the last few site-check passes, files the check was about to read were gone because the site was redeployed during the pass (the page, read again, no longer named them). One deploy is normal; this many passes in a row means the site keeps changing under the check. Ask whether someone is deploying repeatedly; if nobody is, treat it as site.integrity: curl the pages twice a few minutes apart and compare the script names and the Content-Security-Policy header, and check the Worker log for 'redeployed during the pass'.",
  "site.no_approved_lists": () =>
    "The site check is running without approved lists, so it judges nothing. Run pnpm site:approved ../web/out on the build you deploy, review the lists, and redeploy the Worker.",
  "indexer.blind": () => "The monitor can't see a chain and the keeper is holding: fix the RPC (quota, outage, switch URLs).",
  "indexer.logs_omitted": (f) =>
    `The second ${or(f.chainName, "")} RPC served ${or(f.omitted, "a watched log")} that the primary never did, in blocks the tick had already re-read from a node well past them, so the monitor's history and its rules missed them (each is listed above with its block and transaction). Either the primary is pruning or lying, or the second served logs from a fork. Open the transactions on the explorer: if they are real, read the events and act on them as their own alerts would have had you (an admin event: see admin.event), and switch ${f.chain === "base" ? "BASE_LOGS_RPC_URL" : "BITTENSOR_RPC_URL"} (or its _SECRET) to another provider, then redeploy. The tick re-reads only ${f.chain === "base" ? "70" : "400"} blocks back, so a missed log is not added by itself: to backfill, rewind the chain's scanned_to below the oldest missing log (the README's "The logs cross-check" says how), and the next ticks re-read from there and store what was missing. This alert is re-sent hourly; it resolves on acknowledgement, or by itself once the store holds every log it named.`,
  "indexer.logs_extra": (f) =>
    `The store holds ${or(f.lacking, "a log")} that the second ${or(f.chainName, "")} RPC, ${f.chain === "base" ? "70" : "400"} blocks past them, doesn't serve (listed above). Usually the second node pruned them (a non-archive node) or lags its own log index: check a transaction on the explorer. If the explorer doesn't have it either, the primary served a log that isn't on the chain: treat the primary as compromised (switch ${f.chain === "base" ? "BASE_LOGS_RPC_URL" : "BITTENSOR_RPC_URL"}, then re-check what the rules decided on it). If it is the second node's pruning, set ${f.chain === "base" ? "BASE_LOGS_RPC_URL_2" : "BITTENSOR_RPC_URL_2"} (or its _SECRET) to an archive endpoint.`,
  "indexer.unverified": (f) =>
    `The second ${or(f.chainName, "")} RPC hasn't answered the hourly logs cross-check for ${or(f.for, "hours")}${f.error ? ` (last error: ${f.error})` : ""}, so the primary's logs aren't being verified meanwhile. Check ${f.chain === "base" ? "BASE_LOGS_RPC_URL_2" : "BITTENSOR_RPC_URL_2"}: every endpoint in its list failed, and a public one may be refusing Cloudflare's egress (HTTP 429) or the batch. Add another keyless provider to the list (one that answers a 100-block eth_getLogs; the indexer README names those that don't), or set a keyed URL in its _SECRET (another provider than the primary's), then redeploy.`,
  "checks.owner_approved": () =>
    "Confirm it was you: a hand approval lets the keeper pay that batch. If it wasn't, rotate Cloudflare access now and hold the keeper (ops/hold.json).",
  "monitor.stalled": () => "Ticks aren't completing (likely the CPU limit): check Workers Observability for the error; the keeper is holding.",
  "monitor.db_failing": () => "The monitor can't write its database (D1 limit or error): check the D1 dashboard; the keeper is holding once the status goes stale.",
  "rail.alpha_vault": (f) =>
    f.contracts === "v3.2"
      ? "ForeverMoney's AlphaVault is paused (by its guardian, or until a time to come) or a migration of it is announced or under way: the keeper won't close batches into it. On v3.2 a paused front door stops new stakes only, not closes: guardian pause() the front door so no new stake fills a batch that may not convert. A batch closed meanwhile parks as tokens in the Bittensor adapter (bridge.parked) and is delivered once the rail is back. While it is paused a payout reverts and is tried again later. During a migration no payout can be sent at all (ForeverMoney's depositLiquid is closed): cancel the queued payout batches (cancelPayoutBatch) before scheduling a replacement rail (runbook 7.7). Ask ForeverMoney why and until when. If a migration is announced (migrationReadyAt set), close the open batch at once (closeBatch with its id; anyone can), convert every token park with deliverParked before it executes, and close nothing after (bridge.parked_tokens_during_migration). A token park left when it executes is a claim ForeverMoney won't honour."
      : "ForeverMoney's AlphaVault is paused (by its guardian, or until a time to come) or a migration of it is announced or under way: the keeper won't close batches into it. Guardian: pause the front door so no one else closes a batch into a rail that may not deliver (deliveries and payouts through a paused AlphaVault revert, so nothing is lost meanwhile), ask ForeverMoney why and until when, and follow the bridge runbook. A migration moves the AlphaVault's holdings to the target named above: before it executes, decide with ForeverMoney whether Cascade's adapter can use the new vault; until then keep the front door paused.",
  "fmtao.mint_surge": () => "FM-TAO on Base rose more than Cascade's payouts explain. Other people's bridging moves supply too: check the bridge's activity before acting.",
  "ccip.undelivered": (f) =>
    `Check the message on ccip.chain.link${f.ccip ? ` (${f.ccip})` : ""}; lanes are sometimes slow. If it stays stuck for hours, raise it with Chainlink.`,
  "ccip.foreign_send": () =>
    "Someone sent a message through our adapter at a Cascade contract; the contract will refuse it (its execution should end in FAILURE). Nothing to do unless it is delivered (then ccip.unexpected_source fires).",
  "keys.keeper_unexplained_tx": (f) =>
    `Usually a keeper call that reverted (it uses the nonce and emits nothing). Check the explorer${f.explorer ? ` (${f.explorer})` : ""}; if it isn't the keeper's, rotate the keeper key.`,
  "batch.past_max_wait": () => "The keeper isn't closing: check that it runs, its ETH, and the front door's state.",
  "stake.add_fee": () =>
    "Bittensor kept part of the vault's stake add, which every holder bears (stakeIdle books what the chain added). Check the transaction: a new chain fee on root stake adds. If it lasts, raise it with Opentensor, and weigh a minimum stake size for stakeIdle (the runbook's buffer rule, 7.6). Nothing to sign at once.",
  "admin.stamp_quiet": (f) =>
    `No owner stamp has been relayed${f["last stamp (the owner's clock)"] ? ` since ${f["last stamp (the owner's clock)"]}` : ""}: the stamp bot's copied-seed defence is off. Check the PC is on, the bot's Task Scheduler task runs pnpm ops stamp --relay-due --live, the relayer has gas on both chains, and the stack has stamps left (pnpm ops stamp --stack <days> --live to sign more). If you turned the bot off on purpose (runbook 7.3), set THRESHOLDS stampQuietS to 0 meanwhile.`,
  "batch.deposits_blocked": (f) =>
    `The open batch${f.batch ? ` ${f.batch}` : ""} is full by the front door's own rule (its deposit or redeem list, half its value limit or of the deposit cap's room, or no room left for a minimum deposit), so it can close at once, and the keeper closes a full batch on its next round, each minute: it hasn't, for ${or(f["readings in a row"], "several")} readings in a row. Check that the keeper runs, its ETH on Base and its Base spend cap (SPEND CAP lines), and whether it holds the batch: the monitor's hold, or the vault's payouts closed while the batch holds unstake requests (rail.payouts_closed; the keeper says closing waits). Meanwhile deposits may be refused (no room for a minimum one), or wait. If it fills again after each close with deposits cancelled before the close, someone is holding it: the levers are the minimum deposit (pnpm ops set-caps <minDeposit> <depositCap> --for-wallet --live) or the guardian's deposit pause (pnpm ops pause front-door --for-wallet), never a changed batch limit left in place: set any limit you change back in the same sitting (runbook 7.10). No funds are at risk.`,
  "cap.exits_consumed": () =>
    "The front door's deposit cap counts TAO that has since left the vault by direct exits on Bittensor (redeemDirect), so new deposits hit the cap sooner. Owner: raise depositCap by the direct exits since the last change (setCaps is immediate either way): pnpm ops set-caps <minDeposit> <depositCap> --for-wallet --live, then sign it (runbook 7.10).",
  "stake.min_near_floor": () =>
    "Bittensor's minimum stake has climbed toward the 0.03 TAO redeem floor. Above it, small queued payouts revert BelowConversionFloor. Raise the front door's minDeposit above the new minimum plus a fee margin (runbook 7.11), and clear small queued payouts and refunds while they still go.",
  "stake.min_at_floor": () =>
    "Bittensor's minimum stake is near the 0.03 TAO redeem floor: queued payouts of the smallest entries can revert BelowConversionFloor now. Raise the front door's minDeposit at once (runbook 7.11). A payout that reverts BelowConversionFloor goes out with the full top-up: whoever sends it pays the whole bridge fee, so its entries are sent whole (their gross, nothing charged), and a floor raised between a chunk's net and its gross doesn't strand it. The keeper chooses it on BelowConversionFloor; to send one by hand, follow runbook 7.11.",
  "rail.payouts_closed": (f) =>
    /disabled on the vault/.test(f.why ?? "")
      ? "The vault's primary bridge is disabled, so the vault can't send payouts: it defers every front-door redeem a batch brings (RedeemDeferred: nothing is taken, the requester keeps the shares and asks again), and queued payouts wait. If you are switching the rails, finish the switch now, the vault's setPrimaryBridge first (runbook section 8). If not, find out who disabled it (admin.exits_state)."
      : /migration/.test(f.why ?? "")
      ? `The vault's primary bridge can't send payouts${f.why ? ` (${f.why})` : ""}, and never will again: ForeverMoney's depositLiquid is closed from the announcement on. The vault defers every front-door redeem meanwhile (RedeemDeferred: nothing is taken, the requester keeps the shares and asks again), so only the payout batches queued before it closed are stuck. ${OPEN_BATCH_CLOSED("when it arrives", "once the replacement rail runs")} Owner: cancel each queued payout batch now (pnpm ops cancel-payouts <key> --for-wallet --live; its redeemers get their shares back; its bounces can't be cancelled and wait for a replacement rail), before you schedule the replacement rail: a cancel stamps the owner's clock and would kill a pending activation. Holders can leave directly on Bittensor (/unstake/bittensor/); smart-wallet holders wait for the replacement rail (runbook 7.7).`
      : `The vault's primary bridge can't send payouts${f.why ? ` (${f.why})` : ""}. While it lasts the vault defers every front-door redeem (RedeemDeferred: nothing is taken, the requester keeps the shares and asks again), and queued payouts wait: they go once the bridge reads open again, so there is nothing to cancel yet. ${OPEN_BATCH_CLOSED("if it arrives while the bridge still can't send payouts (a pause that lifts first lets them burn and be paid)", "once it reads open, if the site shows theirs was deferred")} Ask ForeverMoney why and until when (rail.alpha_vault). If ForeverMoney's own state reads clear, check the adapter's canSendPayouts() on the explorer: a read of the AlphaVault that fails reads closed. If it turns into a migration, cancel the queued payout batches before you schedule a replacement rail (runbook 7.7).`,
  "payout.no_rail": (f) =>
    `The vault burned front-door redeems${f["redeems burned"] ? ` (${f["redeems burned"]})` : ""} while its primary bridge${f["the vault's primary bridge"] && f["the vault's primary bridge"] !== "not read" ? ` ${f["the vault's primary bridge"]}` : ""} read closed${f.why ? ` (${f.why})` : ""}. Since R6 the vault defers every front-door redeem while its primary is disabled or its canSendPayouts() reads false, so its guard didn't hold: the primary has no such view (the vault reads that as open: runbook §8 item 7), its view needed more than 150,000 gas, the vault is a build from before R6, or the monitor reads another bridge than the vault does. This payout batch can't be sent through that bridge (rail.payouts_closed names it too). If the bridge is closed for good (a migration), owner: cancel the batch (pnpm ops cancel-payouts <key> --for-wallet --live; its redeemers get their shares back) before you schedule a replacement rail (runbook 7.7); if it is a pause, it is paid once the bridge reads open. Then check the primary's canSendPayouts() on the explorer, and fix the bridge that let the burn through before the next delivery. A burn a few blocks before "reopened at" may be the bridge reopening between the monitor's readings: read canSendPayouts() at the burn's block on the archive node before treating it as a guard failure.`,
  "payout.bounces_stranded": () =>
    "A payout batch holding only bounced deposits waits on a front door or bridge that is going. A bounce can't be cancelled: it is paid only once its door is Active and the vault's primary bridge sends again. Don't retire the door or the rail while it is queued; reopen them (runbook section 9) and let it be paid.",
  "payout.overdue": () => "The keeper isn't paying out: check it runs and its TAO; processPayouts is open to anyone after the delay.",
  "delivery.overdue": () => "The keeper can't deliver USDC: check the TWAP oracle and the floors in the keeper's log; the user can still claim.",
  "keeper.low_eth": (f) =>
    `Top up the keeper wallet's ETH on Base${f.needed ? ` to well above ${f.needed}` : ""} (about 0.03 ETH: pnpm ops budget prints it, runbook 2.2). A close sends a float of three times its bridge fee quote${f["the float a close sends"] ? ` (${f["the float a close sends"]} for a full batch now)` : ""} and the front door sends back what the fee leaves, but a node refuses the send unless the wallet holds the whole float and the gas: below it, a full batch can't be closed by the keeper, and the batch waits on Base until someone else closes it.`,
  "keeper.low_tao": (f) =>
    `Top up the keeper wallet's TAO on Bittensor${f.needed ? ` to more than ${f.needed}` : ""}. Bittensor takes a claim's whole gas limit up front${f["a claim's gas up front"] ? ` (${f["a claim's gas up front"]})` : ""}, so a keeper below this can't claim the vault's rewards at all, even though each claim costs far less once the unused gas is refunded.`,
  "guardian.low_eth": (f) =>
    `Send ETH on Base to the guardian ${or(f.guardian, "(the address the front door's guardian() names)")}${f["kept for two pauses"] ? `, to well above ${f["kept for two pauses"]}` : ""} (about 0.001 ETH was its launch funding; pnpm ops budget prints its share of the gas); any account can send it. The guardian signs the emergency pause() and disableBridge on the front door (runbook 7.1), and a wallet won't send a call its account can't pay for: with no ETH it can't pause. ${GUARDIAN_GAS}`,
  "guardian.low_tao": (f) =>
    `Send TAO on Bittensor's EVM to the guardian ${or(f.guardian, "(the address the vault's guardian() names)")}${f["kept for two pauses"] ? `, to well above ${f["kept for two pauses"]}` : ""} (about 0.01 TAO was its launch funding); any account can send it, to its 0x address on chain 964. The guardian signs the emergency pause() of the vault, its disableBridge and its cancel of a scheduled change (runbook 7.1), and Bittensor takes a transaction's whole gas limit up front: with too little it can't pause the vault at all. ${GUARDIAN_GAS}`,
  "keeper.idle_unstaked": () => "The keeper isn't staking (or isn't running): check it.",
  "adapter.low_reserve": () => "Top up the Bittensor adapter's reserve with fundReserve().",
  "twap.divergence": () => "Deliveries may stall (or the pool is being pushed). Watch the pool; users can claim by hand.",
  "price.reference_unavailable": () => "The depeg rule can't run; check the price sources (PRICE_SOURCES).",
  "pool.liquidity": () => "Swaps cost more; consider lowering batch and deposit limits.",
  "batch.one_wallet": () => "One wallet is filling batches; watch for griefing of the cap or the lists.",
  "cap.nearly_full": () =>
    "New deposits will soon be refused. The cap counts what the front door sent to the vault, and only payouts back to Base take it off: if the door's depositors left by direct exits on Bittensor, their TAO still fills it. Then raise depositCap by the difference (runbook 7.10); otherwise decide whether to raise the cap. Near the cap the front door closes a batch with deposits at once when they reach half the room the cap had left, or leave no room under it for a minimum deposit, as it does a batch at half its value limit; a batch of unstakes alone waits for its interval even at the cap.",
  "batch.deposits_full": () =>
    "Deposit lists keep reaching half their slots with deposits near the minimum, and each such list closes at once (the front door's list half rule), its bridge fee paid by its closer, mostly the keeper. Once is an honest rush; again and again, someone may be forcing closes to spend the keeper's ETH (its Base spend cap is 0.01 ETH a day). Check the keeper's ETH; if it goes on, raise minDeposit with setCaps (immediate) so each forced close costs more to force (runbook 7.10).",
  "batch.cancel_churn": (f) =>
    `${f.address ? `Address ${f.address}` : "One address"} has cancelled ${or(f["cancelled in all"], "a lot")} of deposits in open batch ${or(f.batch, "")} (${or(f.cancels, "several")} cancels). That is the pattern of a holder that deposits the batch full just after a keeper round and cancels before the next, so honest deposits are refused (BatchValueFull) for most of each minute. No funds are at risk, and the holder pays only gas: any close that lands while the batch is full commits the holder's deposit (the keeper's each minute, a depositor's own from the site, which offers to close the batch first, or yours: pnpm ops close --live). If it goes on, the levers are the minimum deposit (pnpm ops set-caps <minDeposit> <depositCap> --for-wallet --live) or the guardian's deposit pause, set back in the same sitting (runbook 7.10). One honest user cancelling a few times needs nothing.`,
  "unstakes.tiny_wave": () => "Someone may be pushing honest exits into later batches; watch the next batches.",
  "unstakes.wash": (f) =>
    `A holder${f.user ? ` (${f.user})` : ""} deposited and then unstaked through Base${f.apart ? ` (${f.apart} apart)` : ""}. Since R4 the zero-risk wash, a deposit and a redeem of the same shares in one batch, is refused: the one-day hold defers it (RedeemDeferred), and a burn in one batch takes only older shares. What is left is the spec's stated residual (§3.5): a holder with a day of price exposure and enough capital can still take the day's first-come allowance, depositing one day and unstaking the next, rotating capital and addresses. Usually it is an honest holder who changed their mind, or unstaked too early: acknowledge it. If the same holders come back day after day and take much of the day's allowance (outflow.near_limit) while other unstakes are deferred, honest exits are being crowded: the deeper fix, an allowance shared pro rata, is a contract change for the founder to decide before other people's money. Nothing to sign at once.`,
  "outflow.near_limit": (f) =>
    f.contracts === "v3.2"
      ? "Exits beyond the allowance will be deferred: expect RedeemDeferred (nothing is taken; the holder keeps the shares and asks again). On v3.2 a deferral also comes from the one-day hold on shares less than a day old, and from the vault's bridge unable to send payouts (rail.payouts_closed), so a RedeemDeferred alone doesn't mean the limit: vault.events names each one's likely cause."
      : "Exits beyond the allowance will be deferred; expect RedeemDeferred.",
  "rewards.uncollected": () => "Run pnpm ops claim --live.",
  "validator.not_earning": () => "The validator may have stopped earning (deregistered, offline): check it on taostats; consider moving stake.",
  "vault.events": (f) =>
    f.event === "vault RedeemDeferred" && f.contracts === "v3.2"
      ? `A front-door unstake was deferred: nothing is taken, the holder keeps the shares and asks again (the request fee isn't refunded). On v3.2 it has four causes and names none: shares less than a day old (the one-day hold), the vault's bridge unable to send payouts (rail.payouts_closed), the day's allowance or the entry limit spent (outflow.near_limit), or a request under 0.03 TAO.${f["why (the likely cause)"] ? ` The likely one here: ${f["why (the likely cause)"]}.` : ""} A one-off is a user's edge case; many at once, look at the cause's own alert.`
      : "Read the event in the email; usually a user-level edge case.",
  "vault.stake_moved": (f) =>
    `The vault moved root stake onto its stake hotkey (moveStake or removeHotkey: owner only${f.sender && f.sender !== "not known yet" ? `, sent by ${f.sender}` : ""}). If it was your own change, acknowledge it. If not, treat the owner key as compromised: guardian pause() the vault, then rotate.`,
  "vault.stake_moved_unexpected": (f) =>
    `Stake was moved ${f.to && f["configured stake hotkey"] && f.to !== f["configured stake hotkey"] ? `to hotkey ${f.to}, which isn't the configured stake hotkey ${f["configured stake hotkey"]} (the vault's stake hotkey was changed first: see the StakeHotkeySet alert)` : `in a large amount (${or(f.asked, "see the facts")}) at once`}. Only the owner can move stake${f.sender && f.sender !== "not known yet" ? ` (sent by ${f.sender})` : ""}. If you didn't, assume the owner key is compromised: guardian pause() the vault now, then rotate; check where the stake sits on taostats${f.to ? ` (https://taostats.io/hotkey/${f.to})` : ""}.`,
  "vault.direct_use": (f) =>
    f.event === "vault RedeemOriginSet"
      ? `A holder chose with setRedeemOrigin which chain's front doors may redeem their shares${f.origin ? ` (${f.origin})` : ""}, or none (direct redeems on Bittensor only). That is their own routing and moves nothing; the launch doesn't offer it. A redeem request on Base from a holder whose origin is elsewhere is skipped (RedeemSkipped) and its fee is spent for nothing. Check the user${f.user ? ` (https://evm.taostats.io/address/${f.user})` : ""}; acknowledge if it is a holder you know.`
      : f.contracts === "v3.2"
      ? `Someone used the vault directly on Bittensor (depositDirect or redeemDirect), which the launch doesn't offer: none is expected. Check the user${f.user ? ` (https://evm.taostats.io/address/${f.user})` : ""}. A direct deposit can't mint shares at a swap's depressed price: while stake is missing the vault refuses it, and it prices the lower of its booked and visible stake. If the price still looks wrong, guardian pause() the vault.`
      : `Someone used the vault directly on Bittensor (depositDirect, redeemDirect or allowFrontDoorRedeems), which the launch doesn't offer: none is expected. Check the user${f.user ? ` (https://evm.taostats.io/address/${f.user})` : ""}. A direct deposit while the share price is depressed (a hotkey swap: see stake.divergence and price.drop) mints shares cheaply: if the price isn't right, guardian pause() the vault (depositDirect and redeemDirect stop while paused).`,
  "vault.direct_use_large": (f) =>
    f.contracts === "v3.2"
      ? `A direct ${f.event?.includes("Redeemed") ? "redeem" : "deposit"} above the size threshold${f.hold === "on" ? ", or while a hold is on" : ""}. While stake is missing the vault refuses a direct deposit, so none minted at a swap's depressed price. Check the share price and the user${f.user ? ` (https://evm.taostats.io/address/${f.user})` : ""}; if either looks wrong, guardian pause() the vault until it is explained.`
      : `A direct ${f.event?.includes("Redeemed") ? "redeem" : "deposit"} above the size threshold${f.hold === "on" ? ", or while a hold is on (the share price is in doubt)" : ""}. Guardian: pause() the vault until the price is checked (depositDirect and redeemDirect stop while paused). If the price was depressed when a deposit minted, the shares it got are the loss: find the cause (stake.divergence, price.drop) before unpausing, and check the user${f.user ? ` (https://evm.taostats.io/address/${f.user})` : ""}.`,
  "fmtao.backing_true": (f) =>
    f.side === "lock"
      ? `${or(f["share of wTAO's supply"], "More than 5%")} of wTAO's supply (${or(f["wTAO outside the lock pool"], "see the facts")}) has sat outside the CCIP lock pool for over an hour: wTAO left the pool without FM-TAO being burned for it (a drain by the pool's owner or rebalancer, or a release a forged message asked for), so FM-TAO on Base and Robinhood isn't fully backed; or, less likely at this size, someone minted that much wTAO with the AlphaVault's depositLiquid (anyone can) and keeps it. Nothing is held for this (a stranger could cause it). Look at wTAO's largest holders and the lock pool's last transfers on the explorer (${or(f.lockPool, "the lock pool")}): wTAO released from the pool to an address that burned no FM-TAO for it is a drain: guardian pause() the front door and the vault, tell ForeverMoney and Chainlink, watch fmtao.unbacked. A holder that deposited TAO for it is no drain: acknowledge (raise lockOutsideCriticalBps if it stays).`
      : `${f["a stake of 0"]?.startsWith("yes") ? "ForeverMoney's AlphaVault reads no stake at all (its backing is 0): most likely its validator swapped its hotkey, so its conversions both ways revert until ForeverMoney repoints it (migrateValidator). Unstakes from Base delivered meanwhile can burn into the payout queue and wait until then; owner: cancelPayoutBatch(key, payouts) gives their shares back (runbook 7.8). Tell ForeverMoney now. " : ""}ForeverMoney's AlphaVault holds less TAO than wTAO's supply (${or(f["backing / supply"], "under 100%")}): a loss of the AlphaVault, or wTAO minted without backing, so FM-TAO on every lane (Base, Robinhood) isn't fully backed. ${f.hold?.startsWith("on") ? "The keeper is held: a payout would send users' TAO into this rail." : "The keeper is NOT held (BACKING_HOLD is off): it may still pay out into this rail."} ${f.contracts === "v3.2" ? RAIL_V32("tell ForeverMoney (their 2-of-3 Safe runs the AlphaVault and both pools) and Chainlink; check the AlphaVault on the explorer") : "Guardian: pause() the front door (new batches stop) and the vault (payouts stop); tell ForeverMoney (their 2-of-3 Safe runs the AlphaVault and both pools) and Chainlink; check the AlphaVault on the explorer."} Unpause${f.hold?.startsWith("on") ? " and clear the hold" : ""} only once the backing is back over wTAO's supply. Users' TAO already in the vault is unaffected (it is staked on Bittensor, not held as wTAO). If the backing only dipped within its normal swing (a week of hour rows shows it), widen backingToleranceBps as the README says.`,
  "fmtao.lock_outside": (f) =>
    `${or(f["wTAO outside the lock pool"], "100 TAO or more")} of wTAO has sat outside the CCIP lock pool for over an hour (${or(f["share of wTAO's supply"], "a small share")} of its supply). Usually someone bridged wTAO back to Bittensor, or minted it with the AlphaVault's depositLiquid (anyone can), and holds it unwrapped: no harm to Cascade. It can also be the start of a drain (wTAO released from the pool to someone who burned no FM-TAO for it). Look at wTAO's largest holders and the lock pool's last transfers on the explorer${f.lockPool ? ` (${f.lockPool})` : ""}; acknowledge a holder; if it is a drain, act as fmtao.backing_true says. Above 5% of the supply for an hour this becomes fmtao.backing_true's critical.`,
  "fmtao.role_change_critical": (f) =>
    `ForeverMoney's admin changed something that can move or mint the rail's tokens: ${or(f["what it means"], "see the event above")}. This is ForeverMoney's 2-of-3 Safe acting (or someone who took it over); Cascade can't undo it. Ask ForeverMoney whether it was planned (a pool upgrade grants MINTER_ROLE to the new pool and adds remote pools, all events of one transaction listed in one email; a planned admin move is announced). If not, or until you know: ${f.contracts === "v3.2" ? RAIL_V32("watch fmtao.backing_true, fmtao.mint_surge and fmtao.depeg") : "guardian pause() the front door (no new batch crosses) and the vault (no payout crosses), and watch fmtao.backing_true, fmtao.mint_surge and fmtao.depeg."} A lane bucket at capacity 0 is a bucket switched off: on TokenPool 1.5.1 capacity 0 is only allowed with the limit disabled, so that direction has no limit (a forged message could move everything at once); only a ChainRemoved freezes a lane. After a planned pool upgrade, point the monitor at the new pools: set TOKENS.base.tokenPool (Base) and TOKENS.bittensor.lockPool (Bittensor) in wrangler.jsonc to the new addresses and redeploy, otherwise the lane buckets, fmtao.unbacked, fmtao.backing_true's lock side and these events keep watching the old pools. Deploy that change at least three hours after the new pool's own setup transactions: the hourly logs cross-check judges each block once, about 80 to 140 minutes after it on Bittensor (3 to 25 on Base), with the addresses watched then, so a run after the change would find the new pool's setup events, which the tick wasn't watching for yet, as an indexer.logs_omitted critical. Sooner, expect that one alert, check it lists only the new pool's setup, and acknowledge it.`,
  "fmtao.role_change": (f) =>
    `ForeverMoney changed an admin setting of the rail: ${or(f["what it means"], "see the event above")}. Usually routine (a role revoked, an ownership transfer accepted, a rate limit tuned). Check it matches something ForeverMoney announced, and acknowledge. If it doesn't, ask them; a change you can't explain that touches minting, the lane or an admin is reason to pause as fmtao.role_change_critical says.`,
  "rail.pool": (f) =>
    `The CCIP pool Cascade's batches cross has changed on ${or(f.setting?.startsWith("TOKENS.base") ? "Base" : f.setting ? "Bittensor" : undefined, "one chain")}: ${or(f.why, "see the facts")}. ForeverMoney's Safe can do this at once (setPool in Chainlink's TokenAdminRegistry, or the pool's lane and rate-limit settings), and the keeper and the site don't see it. A pool that isn't ForeverMoney's takes the next batch or payout sent through it, since CCIP's router hands a send's tokens to whatever pool the registry names. ${f.contracts === "v3.2" ? RAIL_POOL_V32 : "Guardian: pause() the front door and the vault until the pool is checked, and ask ForeverMoney what changed."} If they moved the token to a new pool on purpose, check the new pool's roles and lanes, then set ${or(f.setting, "TOKENS.base.tokenPool or TOKENS.bittensor.lockPool")} in wrangler.jsonc to it and redeploy (at least three hours after the new pool's setup: see fmtao.role_change_critical); unpause once rail.pool clears (the registry names ForeverMoney's pool again).`,
  "rail.pool_low": (f) =>
    `${or(f.pool, "A CCIP pool")}'s bucket for Cascade's batches has held less than a full batch (${or(f["a full batch"], "maxBatchValue")}) for over an hour: ${or(f.left, "little")} left, refilling at ${or(f["refills at"], "its rate")}. A batch bigger than what is left waits for it. Usually other people's bridging; it clears by itself. If it stays low, ask ForeverMoney whether the lane is throttled on purpose, and keep batches small meanwhile.`,
  "fmtao.rebalancer_set": (f) =>
    `The CCIP lock pool on Bittensor has a rebalancer, ${or(f.rebalancer, "(see the facts)")}: that account can withdraw all the wTAO locked behind every FM-TAO (withdrawLiquidity), and setting it logged nothing. ForeverMoney's Safe set it. Ask them now why. Until you know: ${f.contracts === "v3.2" ? RAIL_V32("watch for LiquidityRemoved (fmtao.role_change_critical) and fmtao.backing_true") : "the guardian should pause() the front door (no new FM-TAO enters a rail that may be drained) and the vault (no payout crosses into it), and watch for LiquidityRemoved (fmtao.role_change_critical) and fmtao.backing_true."} If they confirm it is planned and short, acknowledge; it resolves when the rebalancer is cleared.`,
  "fmtao.registry_admin": (f) =>
    `${or(f.token, "The rail's token")}'s administrator in Chainlink's TokenAdminRegistry is being moved to ${or(f["proposed administrator"], "another account")}; once that account accepts, it can point the token at any pool it likes (setPool, at once). Ask ForeverMoney whether it is theirs (a Safe rotation). If not, tell them now: their administrator can still cancel it by proposing itself again. Be ready to pause the front door and the vault as rail.pool says.`,
  "rail.alpha_vault_admin": (f) =>
    `ForeverMoney's AlphaVault has a default-admin transfer pending${f["new admin"] ? ` to ${f["new admin"]}` : ""}${f["it may accept from"] ? `, which can be accepted from ${f["it may accept from"]}` : ""}. The admin controls the AlphaVault's roles, so who holds TAO for the rail. Ask ForeverMoney whether it is theirs (a Safe rotation). If not, there is time before the schedule passes: tell them now (their current admin can cancel it), and be ready to pause the front door and the vault as rail.alpha_vault says if it is accepted.`,
  "validator.take_changed": (f) =>
    standby(f)
      ? `The standby validator, which holds part of the vault's stake, changed its take (${or(f.before, "?")} → ${or(f.after, "?")}): the rewards on that part change by as much. If it is still at most 9%, acknowledge. If it is higher (or its Delegates entry is gone, which reads as the chain's default 18%), treat it as validator.take_high.`
      : `The validator Cascade stakes with changed its take (${or(f.before, "?")} → ${or(f.after, "?")}): the vault's rewards change by as much. If it is still small, acknowledge. If its Delegates entry is gone, the chain's default take applies (18%: no entry reads as the default), so treat it as validator.take_high; if the take is high, plan a move to another validator: owner setStakeHotkey(<the new hotkey>) (it adds it to the set), claim this hotkey's rewards (pnpm ops claim), then owner removeHotkey(<this hotkey>, false), which moves its stake onto the new stake hotkey; check the share price after.`,
  "validator.take_high": (f) =>
    standby(f)
      ? `The standby validator's take is ${or(f.take, "high")}, above ${or(f.limit, "the limit")}: it keeps that share of the root dividends on the vault's stake it holds. ${STANDBY_BACK} Not urgent for funds (the stake is safe), urgent for the yield.`
      : `The validator's take is ${or(f.take, "high")}, above ${or(f.limit, "the limit")}: it keeps that share of the vault's root dividends. Move the stake to another validator: owner setStakeHotkey(<the new hotkey>) (it adds it to the set), claim this hotkey's rewards (pnpm ops claim), then owner removeHotkey(<this hotkey>, false), which moves its stake onto the new stake hotkey; check the share price after. Not urgent for funds (the stake is safe), urgent for the yield.`,
  "validator.root_stake_drop": (f) =>
    standby(f)
      ? `The root stake on the standby validator's hotkey fell ${or(f["below the day's high"], "a lot")} below its high of the last day: nominators are leaving. Look it up on taostats${f.taostats ? ` (${f.taostats})` : ""}. Nothing of the vault's is at risk from this alone; if it looks to be winding down: ${STANDBY_BACK}`
      : `The root stake on the validator's hotkey fell ${or(f["below the day's high"], "a lot")} below its high of the last day: nominators are leaving. Look the hotkey up on taostats${f.taostats ? ` (${f.taostats})` : ""} for why (deregistration risk, a take change, a hotkey swap coming). Nothing of the vault's is at risk from this alone; if the validator looks to be winding down, plan a move as validator.take_high says.`,
  "validator.root_uid_lost": (f) =>
    standby(f)
      ? `The standby validator's hotkey has no uid on root any more${f.taostats ? ` (${f.taostats})` : ""}: the vault's stake on it earns no root dividends from now (the stake itself stays the vault's). ${STANDBY_BACK}`
      : `The validator's hotkey has no uid on root any more${f.taostats ? ` (${f.taostats})` : ""}: it was deregistered from root, so the vault's stake on it earns no root dividends from now (the stake itself stays the vault's). Move the stake to a registered root validator: owner setStakeHotkey(<the new hotkey>) (it adds it to the set), claim this hotkey's rewards (pnpm ops claim), then owner removeHotkey(<this hotkey>, false), which moves its stake onto the new stake hotkey; check the share price after. stake.* alerts cover a hotkey swap; this one is the registration.`,
  "ccip.rate_limited": (f) =>
    `CCIP's rate limit on ${or(f.lane, "Cascade's lane")} is nearly spent (${or(f.left, "under 10 TAO")} left in ${or(f.pool, "a pool")}): a batch or payout bigger than that waits until the bucket refills (${or(f["refills at"], "0.6 TAO a second")}). Usually someone bridged a lot at once; it clears by itself. If it stays empty, the lane may be throttled on purpose: check the pool's settings on ccip.chain.link and ask ForeverMoney. Keep batches under the bucket's capacity (maxBatchValue).`,
  "root.hold_interval": (f) => {
    if (f.contracts !== "v3.2") {
      return `Bittensor now holds root stake ${or(f.blocks, "some")} blocks (about ${or(f.about, "?")}) after the last root stake add, remove or claim for its coldkey and hotkey before it can leave root (RootStakeUnlockInterval, a chain setting). Anyone can restart that clock on the vault's coldkey with a tiny transfer_stake, so the vault's unstakes, and the payouts that need them, can be held off for as long as someone keeps doing it. Payouts don't lose funds (they revert and wait). Watch payout.overdue; keep enough unstaked TAO in the vault for the payouts due; if payouts stall, raise it with the Bittensor team. If they stall for long, guardian pause() the front door: there is no redeem-only pause, so it stops new deposits, redeem requests and batch closes alike (claims and cancels still work).`;
    }
    const want = /^(\d+) bps/.exec(f["a buffer that covers the pending payouts and a day's floor"] ?? "")?.[1];
    const capped = want !== undefined && Number(want) > 1000;
    return `Bittensor now holds root stake ${or(f.blocks, "some")} blocks (about ${or(f.about, "?")}) after the last root stake add, remove or claim on a coldkey and hotkey pair before it can leave root (RootStakeUnlockInterval, a chain setting), and anyone can restart that clock on any of the vault's pairs with a tiny transfer_stake. So exits must not need an unstake: the vault pays them from the idle buffer it keeps liquid (${or(f["idle buffer"], "see the facts")}). Owner: setIdleBuffer(${want === undefined ? "<bps>" : capped ? "1000" : want}) now (raising it is immediate) so the buffer covers the pending payouts and a day's floor${capped ? ", the most the vault allows (10% of the booked stake): payouts beyond it wait for the hold" : ""}. Payouts the buffer can't cover revert and wait; nothing is lost. Guardian: pause() the front door (deposits stop; batches of unstakes still deliver and pay out). Founder: fund the buffer with depositDirect() on Bittensor (runbook 7.6). Watch payout.overdue and stake.unstake_skipped, and raise the hold with the Bittensor team. Lower the buffer again (a scheduled change) once the hold is gone.`;
  },
  "root.pair_stamped": () =>
    "A root hold stamp landed on one of the (coldkey, hotkey) pairs the deployment depends on: its unstakes wait out RootStakeUnlockInterval from now. This rule judges nothing yet: the stamp's storage key is read on testnet in Task 62, and until then root.hold_interval (the hold switched on at all) and stake.unstake_skipped (the walk refused on a pair) see it. When it fires: keep the idle buffer up as root.hold_interval says.",
  "oracle.thin_pool": (f) =>
    `The ${or(f.pool, "oracle's")} pool's 30-minute mean liquidity is below the front door's floor, so deliver() refuses every USDC delivery (ThinPool) and the keeper skips them; users can still claim their TAO on Base. One block that drains the pool's range holds it for a whole window (about 30 minutes): usually it clears by itself. If it lasts, see oracle.thin_pool_repeated.`,
  "oracle.thin_pool_repeated": (f) =>
    `The ${or(f.pool, "oracle's")} pool ${f["thin episodes in 24 hours"] ? `has gone thinner than the front door's floor ${/^\d+/.exec(f["thin episodes in 24 hours"])?.[0] ?? "several"} times in 24 hours, deep again between` : `has been thinner than the front door's floor since ${or(f.since, "hours ago")}`}: USDC deliveries are refused round after round. Someone may be holding it thin on purpose (one cheap block every half hour does it, or one before each keeper round, about $88 a hold), or the pool really lost its depth. Check its recent swaps and liquidity on Basescan. Tell the users waiting for a USDC delivery that they can claim their TAO now. Lower the floor (setMinPoolLiquidity, a scheduled change of 48 hours) only if the pool's depth really fell.`,
  "oracle.cardinality": (f) =>
    `The ${or(f.pool, "oracle's")} pool keeps ${or(f.observations, "too few")} observations; the TWAP oracle reads 30 minutes back and needs ${or(f.needed, "1801")}: a pool keeps at most one observation a second, so with a swap every second fewer don't reach back. With fewer, a busy half hour makes usdcValue revert ("OLD") and USDC deliveries stop (oracle.reverted). ${f["growing to"] && Number(f["growing to"]) >= Number(f.needed ?? 1801) ? `It is growing to ${f["growing to"]} by itself as swaps write new observations: nothing to do but wait.` : `Raise it: anyone can call increaseObservationCardinalityNext(${or(f.needed, "1801")}) on the pool (gas only; pnpm ops cardinality prints the steps); it grows as swaps follow.`}`,
  "oracle.reverted": (f) =>
    `The TWAP oracle's usdcValue reverts${f.oracle ? ` (${f.oracle})` : ""} (or its answer doesn't decode: the reading counts both as a revert): the keeper can't price a sale, so USDC deliveries stop. Users still have their TAO on Base and can claim it. Usually the pool's observations don't reach 30 minutes back (see oracle.cardinality: call increaseObservationCardinalityNext on the pool) or the pool is broken; it clears when the window is covered again. If it lasts, tell users deliveries are paused; the front door's owner can point it at another oracle (setOracle) once one is deployed and checked.`,
  "payout.fee_ceiling": (f) =>
    `CCIP's fee for a payout chunk is ${or(f["share of maxFeeAbs"], "near")} of the vault's maxFeeAbs (${or(f.maxFeeAbs, "?")}). The vault refuses a chunk whose fee passes max(sum × maxFeeBps / 10,000, maxFeeAbs) (FeeTooHigh), so once the fee passes maxFeeAbs, small payouts stick (${or(f["a chunk is refused below"], "the smallest chunks")}). Owner: raise maxFeeAbs with setFeeLimits(bps, abs) (at most 0.1 TAO) before it is reached, if the fee stays high.`,
  "batch.redeem_fee_thin": (f) =>
    `A full redeem list's fees (${or(f["a full redeem list pays"], "the redeem request fee times maxRedeems")}) cover the bridge fee to close a full batch (${or(f["a full batch's close quote (50 + 50)"], "the quote")}) only ${or(f.cover, "a little")}. A redeem request needs only its fee, no shares, so anyone can fill the list with fake ones; while the fees cover the close, the pot pays it and the spam pays for itself. Below the quote, a junk-filled list can't close itself (the next request reverts InsufficientFee) and the keeper pays the rest from its ETH. No user funds are at risk. Owner: raise the fee with setRedeemRequestFee(fee) on the front door, immediate, at most 0.001 ETH (MAX_REDEEM_REQUEST_FEE)${f["the fee that covers 1.5×"] ? `: ${f["the fee that covers 1.5×"]} covers 1.5 times now` : ""}. The launch's 0.0002 ETH covers a full batch about 2.3 times at the 0.0043 ETH quote of 2026-10-21, so a warning at that fee means the quote has risen past about 0.0067 ETH (runbook section 4). No ops command writes setRedeemRequestFee yet (the sign page refuses a call it doesn't know): until one is added, the fee stays the constructor's, SETTINGS_V32_LAUNCH.frontDoor.redeemRequestFee, so have the command added before you need it. Honest users pay it once per batch they request in.`,
  "payout.entry_above_cap": (f) =>
    `A queued payout entry is bigger than the vault's primary bridge carries in one message (${or(f["it carries at most"], "its maxMessageValue")}), so the chunk that holds it can't be sent (the bridge refuses it: MessageTooLarge) and the batch's payouts wait behind it. Nothing is lost. Owner: schedule setPrimaryBridge to a pair whose maxMessageValue covers it, send the batch (pnpm ops payouts), then switch back. Before switching to a smaller cap again, drain every queued batch first.`,
  "bridge.parked": (f) =>
    f.unseen
      ? `The Bittensor adapter${f.adapter ? ` ${f.adapter}` : ""} owes more to its parks than the parks the monitor has seen (${or(f.unseen, "see the facts")}), for over an hour: a BatchParked the logs missed. Read its parks on the explorer and check the logs RPC (indexer.logs_omitted may say more). Then treat each park as below.`
      : `A front-door batch${f.amount ? ` of ${f.amount}` : ""} is parked in the Bittensor adapter${f["held as"] ? ` (${f["held as"]})` : ""} because ${or(f.why, "the vault or the conversion refused it")}. Nothing is lost: the TAO waits in the adapter, and its depositors' shares come when it is delivered. Fix the cause (stake.missing: list the swapped hotkey; a paused vault: unpause; ForeverMoney's rail: rail.alpha_vault), then anyone can deliver it with deliverParked (the keeper's park job does). If it can't be delivered, from ${or(f["refundable from"], "14 days after it parked")} anyone can refund it to its depositors on Base (refundParked, paying the CCIP fee). Pause Base deposits if the cause will last.`,
  "bridge.parked_tokens_during_migration": () =>
    "ForeverMoney has announced a migration of its AlphaVault while a batch is parked as tokens (wTAO) in the Bittensor adapter. A token park left when the migration executes is a claim ForeverMoney won't honour. Now: guardian pause() the front door (new stakes stop), close the open batch at once (closeBatch with its id; anyone can), and convert every token park with deliverParked before the migration's ready time (it converts the tokens even if the vault refuses the TAO). Close nothing after that.",
  "bridge.cushion_low": (f) =>
    `The Bittensor adapter's${f.short ? ` ${f.short}` : " reserve or cushion"} is below half its 0.001 TAO target${f["token cushion"]?.startsWith("0 TAO booked") ? " (the token cushion is empty: nothing was ever booked, or every rao of it covered a shortfall)" : ""}. These cover a conversion that comes out 1 rao short: the native reserve on a delivery, the token cushion on a payout send or a converted refund. A few rao under the target is expected: anyone's sweepSurplus leaves exactly the reserve's target, the booked cushion falls a rao for each shortfall it covers, and either covers about a million such shortfalls, so this warns only below half its target. Empty, a short delivery parks as tokens (delivered once topped up) and a short send reverts until topped up; nothing is lost. Top up: the native reserve with fundReserve() (any amount of TAO); the token cushion by approving that much wTAO to the adapter, then fundCushion(amount), which books it. A plain transfer of wTAO is surplus, not cushion: anyone's sweepSurplus sends it to the treasury${f["unbooked surplus (the sweep's)"] && !/^(0 TAO|not read)$/.test(f["unbooked surplus (the sweep's)"]) ? ` (${f["unbooked surplus (the sweep's)"]} lies there now)` : ""}. A surplus never refills the token cushion, even below its target: only fundCushion does. An empty cushion on a new deployment means its funding step (approve, then fundCushion) was missed.`,
  "bridge.refunded": (f) =>
    f.door === "no"
      ? "Someone refunded a stranger's parked batch (not the front door's): its tokens went back to its own sender on Base. Nothing of Cascade's moved; acknowledge."
      : "A parked batch was refunded to the front door on Base after 14 days: each depositor's deposit is claimable there again (a payout from the vault, chunk 4294967295). Its redeem requests were never burned and are gone: those users keep their shares and request again. If you didn't expect it, find out why the park couldn't be delivered (bridge.parked said why).",
  "bridge.dropped": () =>
    "An empty parked batch (redeem requests only, no TAO) was dropped after 14 days. Nothing is owed: its redeems were never burned, so those users keep their shares and request again. Acknowledge.",
  "bridge.retire_blocked": (f) =>
    `The Bittensor adapter ${or(f.adapter, "")} is no longer the vault's primary bridge but still holds parks (${or(f.parked, "see the facts")}). Never retire a pair while it owes parks: deliver each one (deliverParked), or refund it after 14 days (refundParked); drop the empty ones (dropParked). A stranger's park (not from the front door) can be refunded at your fee or left. Keep the pair in BRIDGES until it reads 0 on both totals.`,
  "bridge.parked_stranger": () =>
    "Someone else's batch parked in the Bittensor adapter: it came through the Base adapter from another sender, or to another recipient than the vault, and the recipient refused it. Only its own sender's tokens are stuck; nothing of Cascade's is owed. Nothing to do: after 14 days anyone can refund it (refundParked, at their fee) or drop it if empty. A stream of these is someone griefing the alerts: acknowledge them.",
  "indexer.lag": () => "The monitor is behind on a chain and the keeper is holding: check the logs RPC first (state reads may still work).",
  "bridge.check_stuck": (f) =>
    `The keeper won't pay this batch until its check is ok. Find out why (usually Base lag); if you have verified the batch by hand: pnpm checks:approve -- --env <env> --key ${or(f.key, "<delivered key>")} --note "…".`,
  "bridge.payout_unchecked": () =>
    "A payout landing on Base hasn't been checked, and its TAO is already claimable there. Find out why (usually Bittensor lag, or the front door's delivered() read not answering). Verify the landing against the vault's PayoutChunkSent by hand; if you can't soon, guardian: pause() the front door.",
  "indexer.reorg": () => "Usually harmless; if it was a Cascade transaction, re-check its effects.",
  "site.unreachable": () => "Check that the site is up (Pages, DNS).",
  "monitor.chain_unreadable": () => "Check the RPC URLs (the readings of this chain have failed or gone backwards five ticks in a row).",
  "monitor.email_failing": () => "Check the email binding and the destination address (Email Routing).",
  "monitor.unjudged": (f) =>
    f.lens
      ? `The lens at ${f.lens} reads ${or(f["it reads"], "another contract")}, not this deployment's. The monitor reads nothing through it, so the rules that need it can't judge. Set ${or(f.setting, "the lens in DEPLOYMENT")} to this deployment's lens and redeploy.`
      : f.record
      ? `The monitor's ${or(f.record, "record")} doesn't read (${or(f.error, "it isn't what the monitor writes")}). Every Scheduled, Executed and Cancelled is still emailed, but pending owner changes aren't judged or shown, and new ones aren't recorded, until it reads again. Look at the value in D1 (wrangler d1 execute, SELECT v FROM meta WHERE k = '${(f.record ?? "meta scheduled_items").replace(/^meta /, "")}'). If it can't be repaired, set it to '' (the next ticks record new items again), then check by hand every Scheduled email since it broke: those items aren't tracked.`
      : `The monitor hasn't been able to judge ${or(f.rules, "some critical rules")} for half an hour or more (site.integrity: three hours of incomplete site passes), tick after tick (each one's since is above): a reading it needs is missing, a field in it is unread or doesn't decode, or the rule throws (then monitor.rule_failed carries the error: a bug to fix). A real problem there would go unseen meanwhile; its open alerts stay open. A rule going blind later comes as an alert of its own. If a whole chain is out, monitor.chain_unreadable and indexer.lag say so: fix the RPC. If the chain reads fine, a contract or runtime change broke one read (an AlphaVault upgrade dropping backing(), a Subtensor change to the Delegates, Uids or TotalHotkeyAlpha storage): check that value by hand (the indexer README's Readings list), then fix the read or switch the rule off in THRESHOLDS (rules.off) while you do, and redeploy. Until then watch it yourself: a holding rule that can't judge raises no hold.`,
  "monitor.rule_failed": (f) => `A rule threw${f.error ? ` (${f.error})` : ""}: a bug to fix. The other rules still ran.`,
  "monitor.bridge_rule_failed": (f) =>
    `The bridge cross-check ${or(f.rule, "rule")} threw${f.error ? ` (${f.error})` : ""}. Nothing it would have decided this tick was written: new deliveries and payout landings stay waiting, so the keeper pays none of them out, and forged ones aren't being caught. Fix the bug and redeploy. Approve a delivery by hand (pnpm checks:approve) only after checking it yourself.`,
};
